
































import Vue from 'vue';
import Component from 'vue-class-component';
import { Watch } from 'vue-property-decorator';
import StringService from '@/services/StringService';
import UrlBuilderService from '@/services/UrlBuilderService';
import AuthorsService from '@/services/Api/AuthorsService';
import { Author } from '@/services/Api/AuthorsService/Author.types';
import Loader from '@/components/ui/Loader.vue';
import BooksWithTranslations from '@/components/BooksWithTranslations.vue';
import { getTranslation } from '@/services/Translation';
import { TranslationStrings } from '@/translations/types';

@Component({
  components: { BooksWithTranslations, Loader }
})
export default class AuthorBio extends Vue {
  loading: boolean = false;

  author: Author | null = null;
  getTranslation = getTranslation;

  get authorBooksStat() {
    return (
      this.author &&
      this.author.statistics.languages.map(books => ({
        count: books.count,
        onLanguage: getTranslation(`onLanguage${StringService.capitalize(
          books.lang
        )}` as keyof TranslationStrings)
      }))
    );
  }

  async mounted() {
    await this.fetchAuthor();
    this.updateTabName();
  }

  @Watch('$route')
  async onRouteChange() {
    await this.fetchAuthor();
    this.updateTabName();
  }

  async fetchAuthor() {
    if (this.$route.params.author) {
      this.loading = true;
      this.author = await AuthorsService.getAuthor(this.$route.params.language, this.$route.params.author);
      this.author.books = Object.values(this.author.books).map(book => ({
        ...book,
        translations: book.translations.map(translation => ({
          ...translation,
          url: UrlBuilderService.getBookUrl({ language: translation.lang, bookSlug: book.slug })
        }))
      }));
      this.loading = false;
    }
  }

  updateTabName() {
    this.$store.commit('tabs/updateActiveTabName', this.author ? this.author.name : getTranslation('author'));
  }
}
