





















import Vue from 'vue';
import Component from 'vue-class-component';
import IconInfo from '@/assets/icons/info.svg';
import { getTranslation } from '@/services/Translation';

type ConnectionState = '' | 'offline' | 'restored';

@Component({ components: { IconInfo } })
export default class ConnectionStatus extends Vue {
  status: ConnectionState = '';
  wasOffline = false;
  restoreTimer?: number;
  getTranslation = getTranslation;

  mounted() {
    window.addEventListener('offline', this.handleOffline);
    window.addEventListener('online', this.handleOnline);
    if (!window.navigator.onLine) {
      this.handleOffline();
    }
  }

  beforeDestroy() {
    window.removeEventListener('offline', this.handleOffline);
    window.removeEventListener('online', this.handleOnline);
    this.clearRestoreTimer();
  }

  get title() {
    this.$store.state.reader.interfaceLanguage;
    return getTranslation(this.status === 'restored' ? 'connectionRestored' : 'connectionLost');
  }

  handleOffline() {
    this.clearRestoreTimer();
    this.wasOffline = true;
    this.status = 'offline';
  }

  handleOnline() {
    if (!this.wasOffline) {
      return;
    }
    this.wasOffline = false;
    this.status = 'restored';
    this.clearRestoreTimer();
    this.restoreTimer = window.setTimeout(() => {
      this.status = '';
      this.restoreTimer = undefined;
    }, 3200);
  }

  clearRestoreTimer() {
    if (this.restoreTimer !== undefined) {
      window.clearTimeout(this.restoreTimer);
      this.restoreTimer = undefined;
    }
  }
}
