























import Vue from 'vue';
import Component from 'vue-class-component';
import { Getter, State } from 'vuex-class';
import { BookSection } from '@/services/Navigation/types';
import { Prop } from 'vue-property-decorator';
import UrlBuilderService from '@/services/UrlBuilderService';
import { getTranslation } from '@/services/Translation';
import RelatedNavigationService from '@/services/RelatedNavigationService';
import IconReturn from '@/assets/icons/return.svg';

@Component({ components: { IconReturn } })
export default class BottomBarRelated extends Vue {
  @Getter('currentBookSection', { namespace: 'navigation' })
  currentSection?: BookSection;

  @Prop({ required: true })
  data!: any;

  @Prop({ required: true })
  bookName!: string;

  @State('interfaceLanguage', { namespace: 'reader' })
  interfaceLanguage!: string;

  getTranslation = getTranslation;

  get preparedData() {
    return this.data
      .map((book: any) => ({
        ...book,
        translations: book.translations
          .filter((translation: any) => translation.section_slug)
          .map((translation: any) => {
            const url = UrlBuilderService.getBookSectionUrl({
              language: translation.code,
              bookSlug: book.slug,
              bookSectionSlug: translation.section_slug
            });
            const targetUrl = this.$route.query.reading ? `${url}?reading=1` : url;
            return {
              ...translation,
              url: RelatedNavigationService.createTargetUrl(targetUrl, this.$route.fullPath, this.$route.query
                .relatedTrail as string)
            };
          })
      }))
      .filter((book: any) => book.translations.length > 0);
  }

  get previousRelatedUrl() {
    return RelatedNavigationService.getPreviousUrl(this.$route.query.relatedTrail as string);
  }

  returnToPrevious() {
    if (this.previousRelatedUrl) {
      this.$router.push(this.previousRelatedUrl);
    }
  }

  get textInOtherBooks() {
    return getTranslation('textInOtherBooks')
      .replace('%bookName%', this.bookName)
      .replace('%currentSectionSlug%', this.currentSection ? this.currentSection.slug : '');
  }
}
