import router from '@/router';
import {
  AnyNavEntity,
  Author,
  AuthorLetter,
  Book,
  BookLetter,
  Books,
  BookSection,
  Category,
  ListType,
  NavigationData
} from '@/services/Navigation/types';
import Helpers from '@/services/Navigation/Helpers';

export default class HighlightService extends Helpers {
  public static actualizeHighlight(navigation: NavigationData, listType: ListType, filterQuery: string) {
    // 1. reset all highlights
    navigation = HighlightService.reset(navigation);

    // 2. highlight category
    navigation.categories = HighlightService.highlightCategory(navigation.categories);

    // 3. highlight author
    const { authors, authorIndex } = HighlightService.highlightAuthor(navigation.authors);
    navigation.authors = authors;

    if (authorIndex > -1) {
      // 4. highlight author letter
      navigation.authorsAlphabet = HighlightService.highlightAuthorLetter(
        navigation.authorsAlphabet,
        navigation.authors[authorIndex]
      );
    }

    // 5. highlight book letter
    navigation.booksAlphabet = HighlightService.highlightBookLetter(
      navigation.booksAlphabet,
      navigation.books
    );

    if (HighlightService.needBookHighlight(navigation, listType, filterQuery)) {
      // 6. highlight book
      navigation.books = HighlightService.highlightBook(navigation.books);

      // 7. highlight book section
      navigation.books = HighlightService.highlightBookSection(navigation.books);
    }

    return navigation;
  }

  public static reset(navigation: NavigationData) {
    // reset navigation objects
    navigation.categories = HighlightService.resetEntitiesArray(navigation.categories);
    navigation.authors = HighlightService.resetEntitiesArray(navigation.authors);
    navigation.authorsAlphabet = HighlightService.resetEntitiesArray(navigation.authorsAlphabet);
    navigation.booksAlphabet = HighlightService.resetEntitiesArray(navigation.booksAlphabet);
    navigation.books = HighlightService.resetBooks(navigation.books);
    navigation.books = HighlightService.resetBookSections(navigation.books);
    navigation.foundBooks = HighlightService.resetBooks(navigation.foundBooks);
    navigation.foundBooks = HighlightService.resetBookSections(navigation.foundBooks);
    return navigation;
  }

  public static resetEntitiesArray<T extends Exclude<AnyNavEntity, Book>>(entities: Array<T>): Array<T> {
    (entities as Array<Exclude<AnyNavEntity, Book>>).forEach((one, index) => {
      entities[index].highlight = false;
    });
    return entities;
  }

  public static resetBooks(books: Books) {
    Object.values(books).forEach(book => {
      // reset books
      books[book.slug].highlight = false;
    });
    return books;
  }

  public static resetBookSections(books: Books) {
    Object.values(books).forEach(book => {
      book.children.forEach((bookSection, bookSectionIndex) => {
        books[book.slug].children[bookSectionIndex].highlight = false;
      });
    });
    return books;
  }

  /**
   * Highlights category
   */
  public static highlightCategory(categories: Array<Category>) {
    const routeCategory = router.currentRoute.params.category;
    let highlightedCategory: Category | null = null;
    // find index of category that should be highlighted
    const index = categories.findIndex(category => routeCategory && routeCategory === category.slug);
    if (index > -1) {
      highlightedCategory = categories[index];
      highlightedCategory.highlight = true;
      highlightedCategory.expanded = true;
      // highlight parent categories
      categories = HighlightService.highlightParents(categories, index) as Array<Category>;
    }
    return categories;
  }

  /**
   * Highlights author
   */
  public static highlightAuthor(authors: Array<Author>) {
    const routeAuthor = router.currentRoute.params.author;
    const index = authors.findIndex(author => author.slug === routeAuthor);
    if (index > -1) {
      authors[index].highlight = true;
      authors[index].expanded = true;
    }
    return { authors, authorIndex: index };
  }

  /**
   * Highlight author letter
   */
  public static highlightAuthorLetter(authorsAlphabet: Array<AuthorLetter>, author: Author) {
    const authorId = author.id;
    const index = authorsAlphabet.findIndex(letter => letter.authorIds.find(id => id === authorId));
    if (index > -1) {
      authorsAlphabet[index].highlight = true;
      authorsAlphabet[index].expanded = true;
    }
    return authorsAlphabet;
  }

  /**
   * Highlight book letter
   */
  public static highlightBookLetter(booksAlphabet: Array<BookLetter>, books: Books) {
    const routeBook = router.currentRoute.params.book;
    const book = books[routeBook];
    if (!book) {
      return booksAlphabet;
    }
    const index = booksAlphabet.findIndex(one => one.bookIds.find(id => id === book.id));
    if (index > -1) {
      booksAlphabet[index].highlight = true;
      booksAlphabet[index].expanded = true;
    }
    return booksAlphabet;
  }

  /**
   * Highlights book
   */
  public static highlightBook(origin: Books) {
    const routeBook = router.currentRoute.params.book;
    const books = HighlightService.resetBooks(origin);

    if (books[routeBook]) {
      books[routeBook].highlight = true;
      books[routeBook].expanded = true;
    }
    return books;
  }

  /**
   * Highlights book sections
   */
  public static highlightBookSection(origin: Books) {
    const routeBook = router.currentRoute.params.book;
    const routeBookSection = router.currentRoute.params.bookSection;
    const books = HighlightService.resetBookSections(origin);
    const book = books[routeBook];

    if (!book) {
      return books;
    }

    // find index of item that should be highlighted
    const index: number = book.children.findIndex(
      one => one.book.slug === routeBook && one.slug === routeBookSection
    );

    if (index > -1) {
      // highlight & expand item
      books[routeBook].children[index].highlight = true;
      books[routeBook].children[index].expanded = true;
      // highlight parent sections
      books[routeBook].children = HighlightService.highlightParents(
        books[routeBook].children,
        index
      ) as Array<BookSection>;
    }
    return books;
  }

  public static needBookHighlight(navigationData: NavigationData, listType: ListType, filterQuery: string) {
    return (
      (listType === 'categories' && navigationData.categories.find(one => one.highlight)) ||
      (listType === 'authors' && navigationData.authors.find(one => one.highlight)) ||
      (listType === 'books' && navigationData.booksAlphabet.find(one => one.highlight)) ||
      filterQuery
    );
  }

  public static needBookSectionHighlight(books: Books) {
    return Object.values(books).find(book => book.highlight);
  }

  /**
   * Highlights parents of categories or book sections
   */
  private static highlightParents(array: Array<BookSection | Category>, highlightedIndex: number) {
    return HighlightService.updateParents(array, highlightedIndex, item => ({
      ...item,
      highlight: true,
      expanded: true
    }));
  }
}
