
























import Vue from 'vue';
import UrlBuilderService from '@/services/UrlBuilderService';
import NavRubrics from '@/components/nav/NavRubrics.vue';
import BooksService from '@/services/Api/BooksService';
import Component from 'vue-class-component';
import { getTranslation } from '@/services/Translation';
import { Watch } from 'vue-property-decorator';
import { State } from 'vuex-class';

interface Book {
  language: string;
  slug: string;
  created_at: string;
}

@Component({
  components: { NavRubrics }
})
export default class NewBooks extends Vue {
  newBooksAll: Array<Book> = [];
  newBooks: Array<Book> = [];
  currentLanguage: string = 'all';
  languages: { [key: string]: string } | null = null;
  getTranslation = getTranslation;

  @State('interfaceLanguage', { namespace: 'reader' })
  interfaceLanguage!: string;

  created() {
    this.languages = {
      all: getTranslation('all'),
      ru: getTranslation('onLanguageRu'),
      en: getTranslation('onLanguageEn')
    };
  }

  async mounted() {
    await this.getNewBooks();
  }

  @Watch('interfaceLanguage')
  async onChangeInterfaceLang() {
    this.languages = {
      all: getTranslation('all'),
      ru: getTranslation('onLanguageRu'),
      en: getTranslation('onLanguageEn')
    };
    await this.getNewBooks();
  }

  async getNewBooks() {
    try {
      this.newBooksAll = await BooksService.getNewBooks();
      this.newBooksAll = this.newBooksAll.map(book => ({
        ...book,
        url: UrlBuilderService.getBookUrl({ language: book.language, bookSlug: book.slug })
      }));
      this.changeLanguage('all');
    } catch (e) {
      // do nothing
    }
  }

  prepareMonths() {
    let previousMonth = '';
    this.newBooks = this.newBooks.map(newBook => {
      if (newBook.created_at === previousMonth) {
        return newBook;
      }
      previousMonth = newBook.created_at;
      return {
        ...newBook,
        month: newBook.created_at
      };
    });
  }

  changeLanguage(language: 'all' | 'ru' | 'en') {
    if (language === 'all') {
      this.newBooks = this.newBooksAll.slice(0);
    } else {
      this.newBooks = this.newBooksAll.filter(book => book.language === language);
    }
    this.prepareMonths();
    this.currentLanguage = language;
  }
}
