


























































































































































































































import Vue from 'vue';
import Component from 'vue-class-component';
import { Watch } from 'vue-property-decorator';
import { Getter, Mutation, State } from 'vuex-class';
import { Route } from 'vue-router';
import CommonLayout from '@/layouts/CommonLayout.vue';
import TabsBar from '@/components/TabsBar.vue';
import Search from '@/components/Search.vue';
import NewTab from '@/views/content/NewTab.vue';
import TextTypesFilter from '@/components/TextTypesFilter.vue';
import StorageService from '@/services/StorageService';
import Catalog from '@/views/nav/Catalog.vue';
import NewBooks from '@/views/nav/NewBooks.vue';
import StringService from '@/services/StringService';
import Settings from '@/components/settings/Settings.vue';
import Overlay from '@/components/ui/Overlay.vue';
import IconCross from '@/assets/icons/cross.svg';
import { getTranslation } from '@/services/Translation';
import MobileNavigation from '@/components/mobile/MobileNavigation.vue';
import MobileBookmarks from '@/components/mobile/MobileBookmarks.vue';
import MobileReaderThemePicker from '@/components/mobile/MobileReaderThemePicker.vue';
import MobileBookmarkSheet from '@/components/mobile/MobileBookmarkSheet.vue';
import { LANGUAGE_CODE_DEFAULT, LIST_TYPE_DEFAULT } from '@/constants';
import { getBookKeyFromLink, isBookSectionLink, Tab } from '@/store/modules/tabs';
import NavBookSection from '@/components/nav/NavBookSection.vue';
import { Book, BookSection, ListType } from '@/services/Navigation/types';
import Loader from '@/components/ui/Loader.vue';
import IconArrowDown from '@/assets/icons/arrow-down.svg';
import IconCatalogRu from '@/assets/icons/catalog-ru.svg';
import IconCatalogEn from '@/assets/icons/catalog-en.svg';
import IconCatalogSt from '@/assets/icons/catalog-st.svg';
import IconReturn from '@/assets/icons/return.svg';
import UserService from '@/services/Api/UserService';
import { Bookmark, mapServerBookmark } from '@/store/modules/bookmarks';

type MobileView = 'library' | 'search' | 'search-area' | 'book-search' | 'bookmarks' | 'settings' | 'content';

interface MobileViewTransition {
  finished: Promise<void>;
  ready?: Promise<void>;
  updateCallbackDone?: Promise<void>;
  skipTransition?: () => void;
}

interface ViewTransitionDocument extends Document {
  startViewTransition?: (update: () => Promise<void> | void) => MobileViewTransition;
}

interface MobileVisualViewport {
  width: number;
  addEventListener: (type: 'resize', listener: EventListener) => void;
  removeEventListener: (type: 'resize', listener: EventListener) => void;
}

interface MobileWindow extends Window {
  visualViewport?: MobileVisualViewport;
}

const MOBILE_SECTION_ORDER: { [view in MobileView]: number } = {
  library: 0,
  content: 0,
  search: 1,
  'search-area': 1,
  'book-search': 1,
  bookmarks: 2,
  settings: 3
};

interface ReaderScrollEvent {
  direction: 'up' | 'down';
  delta: number;
  top: number;
  max: number;
}

interface MobileCatalogExpansionState {
  categories: number[];
  authors: number[];
  bookLetters: number[];
  authorLetters: number[];
  books: string[];
  foundBooks: string[];
  sections: string[];
}

interface MobileCatalogState {
  listType: ListType;
  filterQuery: string;
  expanded: MobileCatalogExpansionState;
  scrollTop: number;
}

type MobileCatalogStates = {
  [language: string]: {
    library: MobileCatalogState;
    searchArea: MobileCatalogState;
  };
};

const MIN_LEFT_COLUMN_WIDTH = 288;
const MAX_LEFT_COLUMN_WIDTH = 488;
const LEFT_COLUMN_LOCAL_STORAGE_PARAM = 'leftColumnWidth';
const MOBILE_SEARCH_ROUTE_LOCAL_STORAGE_PARAM = 'mobileSearchRoute';
const MOBILE_CATALOG_STATES_LOCAL_STORAGE_PARAM = 'mobileCatalogStates';
const SAVED_LEFT_COLUMN_WIDTH = parseInt(StorageService.get(LEFT_COLUMN_LOCAL_STORAGE_PARAM));
const SAVED_MOBILE_SEARCH_ROUTES = StorageService.get(MOBILE_SEARCH_ROUTE_LOCAL_STORAGE_PARAM);
const SAVED_MOBILE_CATALOG_STATES = StorageService.get(MOBILE_CATALOG_STATES_LOCAL_STORAGE_PARAM);
const getInitialMobileSearchRoutes = () => {
  if (
    SAVED_MOBILE_SEARCH_ROUTES &&
    typeof SAVED_MOBILE_SEARCH_ROUTES === 'object' &&
    !Array.isArray(SAVED_MOBILE_SEARCH_ROUTES)
  ) {
    return { ...SAVED_MOBILE_SEARCH_ROUTES };
  }
  if (typeof SAVED_MOBILE_SEARCH_ROUTES === 'string') {
    const language = SAVED_MOBILE_SEARCH_ROUTES.split('/').filter(Boolean)[0];
    return language ? { [language]: SAVED_MOBILE_SEARCH_ROUTES } : {};
  }
  return {};
};
const defaultMobileCatalogState = () => ({
  listType: LIST_TYPE_DEFAULT as ListType,
  filterQuery: '',
  scrollTop: 0,
  expanded: {
    categories: [],
    authors: [],
    bookLetters: [],
    authorLetters: [],
    books: [],
    foundBooks: [],
    sections: []
  }
});
const getInitialMobileCatalogStates = (): MobileCatalogStates => {
  if (
    !SAVED_MOBILE_CATALOG_STATES ||
    typeof SAVED_MOBILE_CATALOG_STATES !== 'object' ||
    Array.isArray(SAVED_MOBILE_CATALOG_STATES) ||
    SAVED_MOBILE_CATALOG_STATES.library ||
    SAVED_MOBILE_CATALOG_STATES.searchArea
  ) {
    return {};
  }
  return { ...SAVED_MOBILE_CATALOG_STATES };
};
const BOOK_ROUTE_NAMES = [
  'book',
  'book-section',
  'category-book',
  'category-book-section',
  'author-book',
  'author-book-section'
];
const BOOK_SECTION_ROUTE_NAMES = ['book-section', 'category-book-section', 'author-book-section'];

@Component({
  components: {
    IconCross,
    IconReturn,
    IconArrowDown,
    Loader,
    MobileNavigation,
    MobileBookmarks,
    MobileBookmarkSheet,
    MobileReaderThemePicker,
    NavBookSection,
    Overlay,
    Settings,
    NewBooks,
    Catalog,
    CommonLayout,
    Search,
    TabsBar,
    NewTab,
    TextTypesFilter
  }
})
export default class Reader extends Vue {
  leftColumnWidth: number;

  mobileCatalogVisible: boolean = false;

  mobileLanguageMenuVisible: boolean = false;

  mobileThemePickerVisible: boolean = false;

  mobileBookmarkSheetVisible: boolean = false;

  mobileTocInitializedBookKey: string = '';

  mobileView: MobileView = 'library';

  mobileBookSearchName: string = '';

  mobileBookSearchSlug: string = '';

  mobileSearchOverlayVisible: boolean = false;

  mobileTransitionToken: number = 0;

  mobileActiveTransition?: MobileViewTransition;

  mobileTransitionTimer?: number;

  mobileReaderNavigationRequest?: Promise<void>;

  mobileReaderNavigationKey: string = '';

  mobileSearchRoutes: { [language: string]: string } = getInitialMobileSearchRoutes();

  mobileCatalogStates: MobileCatalogStates = getInitialMobileCatalogStates();

  mobileCatalogRestoreToken: number = 0;

  isCompactViewport: boolean = false;

  isNarrowVisualViewport: boolean = false;

  mobileVisualViewportWidth: number = 0;

  readerChromeVisible: boolean = true;

  readerScrollDirection: 'up' | 'down' | '' = '';

  readerScrollDistance: number = 0;

  readerEndPinToken: number = 0;

  prevPageX: number = 0;

  getTranslation = getTranslation;

  @State('visible', { namespace: 'settings' })
  isSettingsVisible!: boolean;

  @Mutation('hide', { namespace: 'settings' })
  hideSettings!: Function;

  @Mutation('setLanguage', { namespace: 'navigation' })
  setNavLanguage!: Function;

  @Mutation('setReadMode', { namespace: 'reader' })
  setReadMode!: Function;

  @Mutation('setTextTypesFilterVisible', { namespace: 'reader' })
  setTextTypesFilterVisible!: Function;

  @State('language', { namespace: 'navigation' })
  navLanguage!: string;

  @Getter('currentBook', { namespace: 'navigation' })
  currentBook?: Book;

  @Getter('currentBookSection', { namespace: 'navigation' })
  currentBookSection?: BookSection;

  @Getter('checkedBooks', { namespace: 'navigation' })
  checkedBooks!: Array<Book>;

  @Getter('selectedBooksCount', { namespace: 'navigation' })
  selectedBooksCount!: number;

  constructor() {
    super();
    this.leftColumnWidth = Reader.normalizeLeftColumnWidth(SAVED_LEFT_COLUMN_WIDTH) || MIN_LEFT_COLUMN_WIDTH;
  }

  mounted() {
    this.updateViewport();
    window.addEventListener('resize', this.updateViewport);
    if (this.visualViewport) {
      this.visualViewport.addEventListener('resize', this.updateViewport);
    }
    document.addEventListener('keydown', this.onDocumentKeydown);
    this.$root.$on('reader-scroll', this.onReaderScroll);
    this.$root.$on('reader-link-selected', this.onReaderLinkSelected);
    this.onRouteChange(this.$route);
    this.hydrateReadingState();
  }

  beforeDestroy() {
    window.removeEventListener('resize', this.updateViewport);
    if (this.visualViewport) {
      this.visualViewport.removeEventListener('resize', this.updateViewport);
    }
    if (this.mobileTransitionTimer !== undefined) {
      window.clearTimeout(this.mobileTransitionTimer);
    }
    document.removeEventListener('keydown', this.onDocumentKeydown);
    this.$root.$off('reader-scroll', this.onReaderScroll);
    this.$root.$off('reader-link-selected', this.onReaderLinkSelected);
    this.readerEndPinToken += 1;
  }

  @Watch('$route')
  onRouteChange(to: Route, from?: Route) {
    this.mobileCatalogVisible = false;
    this.mobileLanguageMenuVisible = false;
    this.mobileThemePickerVisible = false;
    this.mobileBookmarkSheetVisible = false;
    this.readerEndPinToken += 1;
    this.resetReaderScrollIntent();
    if (this.isCompactViewport) {
      if (to.name === 'search-results' && to.query.scope !== '1' && to.query.bookSearch !== '1') {
        this.mobileSearchRoutes[to.params.language] = to.fullPath;
        StorageService.save(MOBILE_SEARCH_ROUTE_LOCAL_STORAGE_PARAM, this.mobileSearchRoutes);
      }
      this.syncMobileViewWithRoute();
      if (!from || to.path !== from.path) {
        this.readerChromeVisible = true;
        this.setTextTypesFilterVisible(false);
      }
    }
    let route = to.path;
    if (to.query) {
      let query = { ...to.query };
      delete query.reading;
      delete query.bookmark;
      const queryString = StringService.objectToQueryString(query);
      route = queryString.length ? `${route}?${queryString}` : route;
    }
    const routeName = to.name || '';
    if (BOOK_ROUTE_NAMES.includes(routeName) && to.params.language && to.params.book) {
      UserService.openReadingTab(to.params.language, to.params.book);
      const isSectionRoute = BOOK_SECTION_ROUTE_NAMES.includes(routeName);
      this.$store.commit('tabs/activateBookTab', {
        bookKey: `${to.params.language}:${to.params.book}`,
        link: route,
        location: isSectionRoute ? to.params.bookSection : undefined,
        preserveLastLocation: !isSectionRoute
      });
    } else {
      this.$store.commit('tabs/activateRouteTab', { link: route });
    }
    if (this.isCompactViewport) {
      this.$store.commit('tabs/keepOnlyActiveTab');
    }
    this.updateNavLanguage();
    if (typeof this.ensureMobileReaderNavigation === 'function') {
      this.ensureMobileReaderNavigation(to);
    }
  }

  @Watch('$store.state.navigation.loading')
  onNavigationLoadingChange(loading: boolean, wasLoading: boolean) {
    if (!this.isCompactViewport || loading || !wasLoading) {
      return;
    }
    if (this.mobileView === 'library' || this.mobileView === 'search-area') {
      this.restoreMobileCatalogState(this.mobileView === 'library' ? 'library' : 'searchArea');
    }
  }

  updateNavLanguage() {
    // initialization of language variable
    // we initialize it here, since it's the parent component for all components in the left column, where this variable could be used
    if (this.isCompactViewport && !this.$route.params.language) {
      if (!this.navLanguage) {
        this.setNavLanguage(LANGUAGE_CODE_DEFAULT);
      }
      return;
    }
    this.setNavLanguage(this.$route.params.language || '');
  }

  ensureMobileReaderNavigation(route: Route) {
    if (
      !this.isCompactViewport ||
      !BOOK_SECTION_ROUTE_NAMES.includes(route.name || '') ||
      !route.params.language ||
      !route.params.book
    ) {
      return;
    }
    const language = route.params.language;
    const bookSlug = route.params.book;
    const sectionSlug = route.params.bookSection || '';
    const cachedSection = this.currentBookSection;
    if (
      cachedSection &&
      cachedSection.book.language === language &&
      cachedSection.book.slug === bookSlug &&
      cachedSection.slug === route.params.bookSection
    ) {
      this.$store.commit('navigation/setError', false);
      return;
    }
    const navigationKey = `${language}:${bookSlug}:${sectionSlug}`;
    if (this.mobileReaderNavigationRequest && this.mobileReaderNavigationKey === navigationKey) {
      return;
    }
    this.mobileReaderNavigationKey = navigationKey;
    this.mobileReaderNavigationRequest = this.prepareMobileReaderNavigation(language, bookSlug, sectionSlug)
      .catch(() => {
        // BookContent owns the visible error state for a failed direct route.
      })
      .finally(() => {
        this.mobileReaderNavigationRequest = undefined;
        this.mobileReaderNavigationKey = '';
      });
  }

  async prepareMobileReaderNavigation(language: string, bookSlug: string, sectionSlug: string = '') {
    this.setNavLanguage(language);
    let navigationData = this.$store.state.navigation.data[language];
    if (!navigationData || !navigationData.booksAlphabet.length) {
      await this.$store.dispatch('navigation/fetch', language);
      navigationData = this.$store.state.navigation.data[language];
    }
    const cachedBook = navigationData && navigationData.books[bookSlug];
    const hasRequestedSection =
      cachedBook &&
      (!sectionSlug ||
        cachedBook.is_article ||
        cachedBook.children.some((section: BookSection) => section.slug === sectionSlug));
    if (hasRequestedSection) {
      this.$store.commit('navigation/setError', false);
      return;
    }
    await this.$store.dispatch('navigation/highlightLetterByBookSlug', {
      language,
      bookSlug
    });
  }

  get activeTab() {
    return this.$store.state.tabs.list.find((tab: { active: boolean }) => tab.active);
  }

  get readerBook() {
    return this.currentBook || (this.currentBookSection && this.currentBookSection.book);
  }

  get readerBookRootSections() {
    return this.readerBook
      ? (this.readerBook.children || []).filter((section: BookSection) => section.depth === 0)
      : [];
  }

  get visualViewport() {
    return (window as MobileWindow).visualViewport;
  }

  get catalogLanguages() {
    return [
      { code: 'ru', label: getTranslation('russian'), icon: IconCatalogRu },
      { code: 'en', label: getTranslation('english'), icon: IconCatalogEn },
      { code: 'st', label: getTranslation('sanskrit'), icon: IconCatalogSt }
    ];
  }

  get currentCatalogLanguage() {
    return (
      this.catalogLanguages.find(language => language.code === this.navLanguage) || this.catalogLanguages[0]
    );
  }

  get isBookSectionRoute() {
    return ['book-section', 'category-book-section', 'author-book-section'].includes(this.$route.name || '');
  }

  get isBookRoute() {
    return ['book', 'category-book', 'author-book'].includes(this.$route.name || '');
  }

  get mobileReader() {
    return this.isCompactViewport && this.isBookSectionRoute;
  }

  get showMobileContent() {
    return (
      this.mobileView === 'content' ||
      (['search', 'book-search'].includes(this.mobileView) && this.$route.name === 'search-results')
    );
  }

  get mobileNavigationView() {
    if (this.mobileView === 'content') {
      return 'library';
    }
    return ['search-area', 'book-search'].includes(this.mobileView) ? 'search' : this.mobileView;
  }

  updateViewport() {
    const wasCompact = this.isCompactViewport;
    this.isCompactViewport = window.innerWidth <= 1024;
    this.mobileVisualViewportWidth = this.visualViewport ? this.visualViewport.width : window.innerWidth;
    this.isNarrowVisualViewport = this.isCompactViewport && this.mobileVisualViewportWidth < 240;
    if (this.isCompactViewport && !wasCompact) {
      this.syncMobileViewWithRoute();
    } else if (!this.isCompactViewport && wasCompact) {
      this.readerChromeVisible = true;
      this.setReadMode(false);
    }
  }

  syncMobileViewWithRoute() {
    if (this.isBookSectionRoute) {
      this.mobileView = 'content';
      this.setReadMode(true);
      return;
    }
    this.setReadMode(false);
    if (this.$route.name === 'search-results') {
      if (this.$route.query.bookSearch === '1' && typeof this.$route.query.slug === 'string') {
        this.mobileView = 'book-search';
        const bookSlug = this.$route.query.slug;
        const bookKey = `${this.$route.params.language}:${bookSlug}`;
        const bookTab = this.$store.state.tabs.list.find(
          (tab: Tab) => tab.bookKey === bookKey && tab.bookName
        ) as Tab | undefined;
        const preservedBookName = this.mobileBookSearchSlug === bookSlug ? this.mobileBookSearchName : '';
        this.mobileBookSearchName = (bookTab && bookTab.bookName) || preservedBookName || bookSlug;
        this.mobileBookSearchSlug = bookSlug;
        this.$store.commit('navigation/setShowSearchResultsFlag', false);
        return;
      }
      this.mobileView = this.$route.query.scope === '1' ? 'search-area' : 'search';
      this.restoreMobileCatalogState(this.mobileView === 'search-area' ? 'searchArea' : 'library');
      this.$store.commit(
        'navigation/setShowSearchResultsFlag',
        this.mobileView === 'search' &&
          typeof this.$route.query.query === 'string' &&
          !!this.$route.query.query
      );
    } else if (this.$route.name === 'mobile-library') {
      this.mobileView = 'library';
      this.restoreMobileCatalogState('library');
      this.$store.commit('navigation/setShowSearchResultsFlag', false);
    } else if (this.$route.name === 'mobile-bookmarks') {
      this.mobileView = 'bookmarks';
    } else if (this.$route.name === 'mobile-settings') {
      this.mobileView = 'settings';
    } else if (this.isBookRoute || this.$route.name === 'author-bio' || this.$route.name === 'help') {
      this.mobileView = 'content';
    } else if (this.$route.path === '/') {
      this.mobileView = 'library';
      this.restoreMobileCatalogState('library');
      this.$store.commit('navigation/setShowSearchResultsFlag', false);
    }
    if (this.mobileView === 'library' && !this.navLanguage) {
      this.setNavLanguage(this.$route.params.language || LANGUAGE_CODE_DEFAULT);
    }
  }

  openMobileView(view: MobileView) {
    const previousView = this.mobileView;
    const navigate = async () => {
      if (previousView === 'search-area') {
        this.saveMobileCatalogState('searchArea');
      } else if (previousView === 'library') {
        this.saveMobileCatalogState('library');
      }
      this.mobileView = view;
      this.mobileCatalogVisible = false;
      this.readerChromeVisible = true;
      this.setTextTypesFilterVisible(false);
      this.setReadMode(false);
      const language = this.$route.params.language || this.navLanguage || LANGUAGE_CODE_DEFAULT;
      if (view === 'library') {
        this.restoreMobileCatalogState('library');
        this.$store.commit('navigation/setShowSearchResultsFlag', false);
        this.setNavLanguage(language);
        const libraryRoute = `/${language}/library`;
        if (this.$route.path !== libraryRoute) {
          await this.$router.push(libraryRoute);
        }
        return;
      }
      if (view === 'search') {
        const savedSearchRoute = this.mobileSearchRoutes[language] || '';
        const searchRoute = this.sanitizeGlobalSearchRoute(savedSearchRoute || `/${language}/search`);
        if (this.$route.fullPath !== searchRoute) {
          await this.$router.push(searchRoute);
        } else {
          this.$store.commit(
            'navigation/setShowSearchResultsFlag',
            typeof this.$route.query.query === 'string' && !!this.$route.query.query
          );
        }
        return;
      }
      if (view === 'bookmarks' || view === 'settings') {
        const route = `/${language}/${view}`;
        if (this.$route.path !== route) {
          await this.$router.push(route);
        }
      }
    };

    const fromIndex = MOBILE_SECTION_ORDER[previousView];
    const toIndex = MOBILE_SECTION_ORDER[view];
    const viewTransitionDocument = document as ViewTransitionDocument;
    const reduceMotion =
      typeof window.matchMedia === 'function' &&
      window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (
      !this.isCompactViewport ||
      fromIndex === toIndex ||
      reduceMotion ||
      !viewTransitionDocument.startViewTransition
    ) {
      navigate();
      return;
    }

    const transitionClass =
      toIndex > fromIndex ? 'mobile-section-transition-forward' : 'mobile-section-transition-backward';
    const transitionToken = ++this.mobileTransitionToken;
    document.documentElement.classList.remove(
      'mobile-section-transition-forward',
      'mobile-section-transition-backward'
    );
    document.documentElement.classList.add(transitionClass);
    if (this.mobileActiveTransition && this.mobileActiveTransition.skipTransition) {
      this.mobileActiveTransition.skipTransition();
    }
    const transition = viewTransitionDocument.startViewTransition(async () => {
      await navigate();
      await this.$nextTick();
    });
    this.mobileActiveTransition = transition;
    if (this.mobileTransitionTimer !== undefined) {
      window.clearTimeout(this.mobileTransitionTimer);
    }
    this.mobileTransitionTimer = window.setTimeout(() => {
      if (this.mobileActiveTransition === transition && transition.skipTransition) {
        transition.skipTransition();
      }
      this.finishMobileViewTransition(transition, transitionClass, transitionToken);
    }, 400);
    if (transition.ready) {
      transition.ready.catch(() => {});
    }
    if (transition.updateCallbackDone) {
      transition.updateCallbackDone.catch(() => {});
    }
    transition.finished.then(
      () => this.finishMobileViewTransition(transition, transitionClass, transitionToken),
      () => this.finishMobileViewTransition(transition, transitionClass, transitionToken)
    );
  }

  finishMobileViewTransition(
    transition: MobileViewTransition,
    transitionClass: string,
    transitionToken: number
  ) {
    if (this.mobileActiveTransition === transition) {
      this.mobileActiveTransition = undefined;
      if (this.mobileTransitionTimer !== undefined) {
        window.clearTimeout(this.mobileTransitionTimer);
        this.mobileTransitionTimer = undefined;
      }
    }
    if (transitionToken === this.mobileTransitionToken) {
      document.documentElement.classList.remove(transitionClass);
    }
  }

  sanitizeGlobalSearchRoute(route: string) {
    const [path, queryString = ''] = route.split('?');
    const query = new URLSearchParams(queryString);
    ['slug', 'bookId', 'inBookOnly', 'bookSearch', 'returnTo', 'index', 'highlight', 'reading'].forEach(
      name => query.delete(name)
    );
    const normalizedQuery = query.toString();
    return normalizedQuery ? `${path}?${normalizedQuery}` : path;
  }

  openMobileBookSearch() {
    const language = this.$route.params.language || this.navLanguage || LANGUAGE_CODE_DEFAULT;
    const book = this.$route.params.book;
    if (!book) {
      return;
    }
    const query = new URLSearchParams({
      slug: book,
      inBookOnly: '1',
      bookSearch: '1',
      returnTo: this.$route.fullPath
    });
    const currentBookId =
      (this.currentBook && this.currentBook.slug === book && this.currentBook.id) ||
      (this.currentBookSection &&
        this.currentBookSection.book.slug === book &&
        this.currentBookSection.book.id);
    if (currentBookId) {
      query.set('bookId', currentBookId.toString());
    }
    const bookTab = this.$store.state.tabs.list.find(
      (tab: Tab) => tab.bookKey === `${language}:${book}` && tab.bookName
    ) as Tab | undefined;
    this.mobileBookSearchName = (bookTab && bookTab.bookName) || book;
    this.mobileBookSearchSlug = book;
    this.$router.push(`/${language}/search?${query.toString()}`);
  }

  closeMobileBookSearch() {
    const returnTo = this.$route.query.returnTo;
    if (typeof returnTo === 'string' && returnTo) {
      this.$store.commit('navigation/setError', false);
      this.$router.replace(returnTo);
      return;
    }
    const language = this.$route.params.language || this.navLanguage || LANGUAGE_CODE_DEFAULT;
    const book = this.$route.query.slug;
    this.$router.push(
      typeof book === 'string' && book ? `/${language}/books/${book}` : `/${language}/library`
    );
  }

  openMobileSearchArea() {
    this.saveMobileCatalogState('library');
    this.restoreMobileCatalogState('searchArea');
    this.$store.commit('navigation/setShowSearchResultsFlag', false);
    this.mobileView = 'search-area';
    this.mobileCatalogVisible = false;
    this.mobileLanguageMenuVisible = false;
    this.readerChromeVisible = true;
    this.setTextTypesFilterVisible(false);
    this.setReadMode(false);
    if (this.$route.name === 'search-results' && this.$route.query.scope !== '1') {
      this.$router.push({ query: { ...this.$route.query, scope: '1' } });
    }
  }

  closeMobileSearchArea() {
    this.saveMobileCatalogState('searchArea');
    this.restoreMobileCatalogState('library');
    this.mobileView = 'search';
    this.readerChromeVisible = true;
    this.$store.commit(
      'navigation/setShowSearchResultsFlag',
      typeof this.$route.query.query === 'string' && !!this.$route.query.query
    );
    if (this.$route.name === 'search-results' && this.$route.query.scope === '1') {
      const query = { ...this.$route.query };
      delete query.scope;
      this.$router.replace({ query });
    }
  }

  changeCatalogLanguage(language: string) {
    if (this.isCompactViewport && this.mobileView === 'library') {
      this.saveMobileCatalogState('library');
    }
    this.setNavLanguage(language);
    this.mobileLanguageMenuVisible = false;
    if (this.isCompactViewport && this.mobileView === 'library') {
      const libraryRoute = `/${language}/library`;
      if (this.$route.path !== libraryRoute) {
        this.$router.push(libraryRoute);
      }
    }
  }

  toggleMobileLanguageMenu() {
    this.mobileLanguageMenuVisible = !this.mobileLanguageMenuVisible;
    if (this.mobileLanguageMenuVisible) {
      this.$nextTick(() => {
        const options = (this.$refs.mobileLanguageOptions || []) as HTMLElement[];
        const selectedIndex = this.catalogLanguages.findIndex(language => language.code === this.navLanguage);
        const selected = options[Math.max(0, selectedIndex)];
        if (selected) {
          selected.focus();
        }
      });
    }
  }

  closeMobileLanguageMenu(restoreFocus: boolean = false) {
    this.mobileLanguageMenuVisible = false;
    if (restoreFocus) {
      this.$nextTick(() => {
        const trigger = this.$refs.mobileLanguageTrigger as HTMLElement;
        if (trigger) {
          trigger.focus();
        }
      });
    }
  }

  onDocumentKeydown(event: KeyboardEvent) {
    if (!this.mobileLanguageMenuVisible) {
      return;
    }
    if (event.key === 'Escape') {
      event.preventDefault();
      this.closeMobileLanguageMenu(true);
      return;
    }
    if (event.key === 'Tab') {
      this.closeMobileLanguageMenu();
      return;
    }
    if (!['ArrowDown', 'ArrowUp'].includes(event.key)) {
      return;
    }
    const options = (this.$refs.mobileLanguageOptions || []) as HTMLElement[];
    if (!options.length) {
      return;
    }
    event.preventDefault();
    const currentIndex = options.indexOf(document.activeElement as HTMLElement);
    const direction = event.key === 'ArrowDown' ? 1 : -1;
    const nextIndex = (currentIndex + direction + options.length) % options.length;
    options[nextIndex].focus();
  }

  saveMobileCatalogState(context: 'library' | 'searchArea') {
    const language = this.$route.params.language || this.navLanguage || LANGUAGE_CODE_DEFAULT;
    const states = this.getMobileCatalogStates(language);
    const scrollElement = this.getMobileCatalogScrollElement(context);
    states[context] = {
      listType: this.$store.state.navigation.listType,
      filterQuery: this.$store.state.navigation.filterQuery,
      expanded: this.captureMobileCatalogExpansion(),
      scrollTop: scrollElement ? scrollElement.scrollTop : states[context].scrollTop || 0
    };
    StorageService.save(MOBILE_CATALOG_STATES_LOCAL_STORAGE_PARAM, this.mobileCatalogStates);
  }

  async restoreMobileCatalogState(context: 'library' | 'searchArea') {
    const language = this.$route.params.language || this.navLanguage || LANGUAGE_CODE_DEFAULT;
    const state = this.getMobileCatalogStates(language)[context];
    const restoreToken = ++this.mobileCatalogRestoreToken;
    if (this.$store.state.navigation.language !== language) {
      this.setNavLanguage(language);
    }
    this.$store.commit('navigation/setListType', state.listType);
    this.$store.commit('navigation/updateFilterQuery', state.filterQuery);
    this.$store.commit('navigation/resetFilter');
    if (state.filterQuery) {
      await this.$store.dispatch('navigation/filter', {
        language,
        query: state.filterQuery
      });
    }
    if (
      restoreToken !== this.mobileCatalogRestoreToken ||
      this.$store.state.navigation.language !== language
    ) {
      return;
    }
    this.$store.commit('navigation/restoreExpansionState', state.expanded);
    await this.$nextTick();
    window.requestAnimationFrame(() => {
      if (restoreToken !== this.mobileCatalogRestoreToken) {
        return;
      }
      const scrollElement = this.getMobileCatalogScrollElement(context);
      if (scrollElement) {
        scrollElement.scrollTop = state.scrollTop || 0;
      }
    });
  }

  getMobileCatalogStates(language: string) {
    if (!this.mobileCatalogStates[language]) {
      this.$set(this.mobileCatalogStates, language, {
        library: defaultMobileCatalogState(),
        searchArea: defaultMobileCatalogState()
      });
    }
    return this.mobileCatalogStates[language];
  }

  getMobileCatalogScrollElement(context: 'library' | 'searchArea') {
    const modeClass = context === 'library' ? 'mobile-library' : 'mobile-search-area';
    const root = this.$el as HTMLElement | undefined;
    if (!(root && typeof root.querySelector === 'function')) {
      return null;
    }
    return root.querySelector(`.left.${modeClass} .nav-catalog-tree-inner`) as HTMLElement | null;
  }

  captureMobileCatalogExpansion(): MobileCatalogExpansionState {
    const data = this.$store.getters['navigation/dataFromStateLanguage'];
    const sections: string[] = [];
    const collectSections = (items: Array<BookSection>, bookSlug: string) => {
      items.forEach(section => {
        if (section.expanded) {
          sections.push(`${bookSlug}:${section.id}`);
        }
        collectSections(section.children || [], bookSlug);
      });
    };
    Object.values(data.books || {}).forEach((book: any) => collectSections(book.children || [], book.slug));
    Object.values(data.foundBooks || {}).forEach((book: any) =>
      collectSections(book.children || [], book.slug)
    );
    return {
      categories: (data.categories || []).filter((item: any) => item.expanded).map((item: any) => item.id),
      authors: (data.authors || []).filter((item: any) => item.expanded).map((item: any) => item.id),
      bookLetters: (data.booksAlphabet || [])
        .filter((item: any) => item.expanded)
        .map((item: any) => item.id),
      authorLetters: (data.authorsAlphabet || [])
        .filter((item: any) => item.expanded)
        .map((item: any) => item.id),
      books: Object.values(data.books || {})
        .filter((item: any) => item.expanded)
        .map((item: any) => item.slug),
      foundBooks: Object.values(data.foundBooks || {})
        .filter((item: any) => item.expanded)
        .map((item: any) => item.slug),
      sections
    };
  }

  openReaderCatalog() {
    this.readerChromeVisible = true;
    this.setTextTypesFilterVisible(false);
    this.mobileThemePickerVisible = false;
    if (this.readerBook && this.mobileTocInitializedBookKey !== this.readerBook.slug) {
      this.$store.commit('navigation/collapseBookTree', this.readerBook.slug);
      this.mobileTocInitializedBookKey = this.readerBook.slug;
    }
    this.mobileCatalogVisible = true;
  }

  toggleMobileThemePicker() {
    this.readerChromeVisible = true;
    this.mobileCatalogVisible = false;
    this.setTextTypesFilterVisible(false);
    this.mobileThemePickerVisible = !this.mobileThemePickerVisible;
  }

  onReaderScroll(event: ReaderScrollEvent | string) {
    if (
      !this.mobileReader ||
      this.mobileCatalogVisible ||
      this.mobileThemePickerVisible ||
      this.$store.state.reader.isTextTypesFiltersVisible
    ) {
      return;
    }
    const scrollEvent: ReaderScrollEvent =
      typeof event === 'string'
        ? { direction: event as 'up' | 'down', delta: 16, top: 100, max: 1000 }
        : event;
    const remaining = Math.max(0, scrollEvent.max - scrollEvent.top);
    if (scrollEvent.top <= 16) {
      this.readerChromeVisible = true;
      this.resetReaderScrollIntent();
      return;
    }
    if (remaining <= 32) {
      const shouldPinEnd = !this.readerChromeVisible;
      this.readerChromeVisible = true;
      this.resetReaderScrollIntent();
      if (shouldPinEnd) {
        this.$nextTick(this.pinReaderToEnd);
      }
      return;
    }
    if (this.readerScrollDirection !== scrollEvent.direction) {
      this.readerScrollDirection = scrollEvent.direction;
      this.readerScrollDistance = 0;
    }
    this.readerScrollDistance += scrollEvent.delta;
    if (scrollEvent.direction === 'down' && this.readerChromeVisible && this.readerScrollDistance >= 72) {
      this.readerChromeVisible = false;
      this.resetReaderScrollIntent();
    } else if (
      scrollEvent.direction === 'up' &&
      !this.readerChromeVisible &&
      this.readerScrollDistance >= 48
    ) {
      this.readerChromeVisible = true;
      this.resetReaderScrollIntent();
    }
  }

  resetReaderScrollIntent() {
    this.readerScrollDirection = '';
    this.readerScrollDistance = 0;
  }

  pinReaderToEnd() {
    const root = this.$el as HTMLElement | undefined;
    if (!(root && typeof root.querySelector === 'function')) {
      return;
    }
    const scroll = root.querySelector('.book-content .scroll') as HTMLElement | null;
    if (!scroll) {
      return;
    }
    const token = ++this.readerEndPinToken;
    const startedAt = performance.now();
    const pin = () => {
      if (token !== this.readerEndPinToken) {
        return;
      }
      scroll.scrollTop = Math.max(0, scroll.scrollHeight - scroll.clientHeight);
      if (performance.now() - startedAt < 240) {
        window.requestAnimationFrame(pin);
      }
    };
    window.requestAnimationFrame(pin);
  }

  showReaderChrome() {
    if (this.mobileReader && !this.readerChromeVisible) {
      this.readerChromeVisible = true;
    }
  }

  async hydrateReadingState() {
    if (!this.$store.state.auth.authorized) {
      return;
    }
    try {
      const readingTabs = await UserService.getReadingTabs();
      this.$store.commit('tabs/mergeServerReadingTabs', readingTabs);
      if (this.isCompactViewport) {
        this.$store.commit('tabs/keepOnlyActiveTab');
      }
    } catch (e) {
      // Local tabs remain available while an older backend is being upgraded.
    }
    try {
      const bookmarks = await UserService.getBookmarks();
      this.$store.commit('bookmarks/mergeServerRecords', bookmarks);
    } catch (e) {
      // Guest and offline bookmarks remain available from local storage.
    }
  }

  currentBookmarkPayload() {
    const activeTab = this.activeTab as Tab | undefined;
    const contentView = (this.$refs && this.$refs.contentView) as
      | { captureCurrentReadingPosition?: () => any }
      | undefined;
    const livePosition =
      contentView && typeof contentView.captureCurrentReadingPosition === 'function'
        ? contentView.captureCurrentReadingPosition()
        : null;
    const tab = livePosition
      ? ({
          ...activeTab,
          bookKey: livePosition.bookKey,
          link: livePosition.link,
          location: livePosition.location,
          position: livePosition.position,
          paragraphAnchor: livePosition.paragraphAnchor
        } as Tab)
      : activeTab;
    if (!(tab && tab.bookKey && tab.link)) {
      return null;
    }
    const [language, book] = tab.bookKey.split(':');
    const segments = tab.link
      .split('?')[0]
      .split('/')
      .filter(Boolean);
    const section = segments[segments.length - 1] === book ? '' : segments[segments.length - 1];
    return {
      language,
      book,
      section,
      position: Number(tab.position) || 0,
      anchor: tab.paragraphAnchor || '',
      tab
    };
  }

  resolveBookmarkSection(bookmark: Bookmark) {
    if (!bookmark.anchor) {
      return '';
    }
    const bookmarkAnchor = bookmark.anchor;
    const data = this.$store.state.navigation.data[bookmark.language];
    const book = data && data.books ? data.books[bookmark.book] : null;
    if (!(book && Array.isArray(book.children))) {
      return '';
    }
    const candidates = book.children
      .map((section: BookSection) => ({
        slug: section.slug,
        anchorPrefix: `paragraph-${String(section.slug || section.id || 'section')
          .toLowerCase()
          .replace(/[^a-z0-9]+/g, '-')
          .replace(/^-|-$/g, '')}-`
      }))
      .sort(
        (left: { anchorPrefix: string }, right: { anchorPrefix: string }) =>
          right.anchorPrefix.length - left.anchorPrefix.length
      );
    const match = candidates.find((candidate: { anchorPrefix: string }) =>
      bookmarkAnchor.startsWith(candidate.anchorPrefix)
    );
    return match ? match.slug : '';
  }

  replaceBookmarkSectionInLink(link: string, bookSlug: string, sectionSlug: string) {
    const segments = link
      .split('?')[0]
      .split('/')
      .filter(Boolean);
    const lastSegment = segments[segments.length - 1];
    if (lastSegment === bookSlug) {
      segments.push(sectionSlug);
    } else {
      segments[segments.length - 1] = sectionSlug;
    }
    return `/${segments.join('/')}`;
  }

  localBookmark(
    payload: ReturnType<Reader['currentBookmarkPayload']>,
    id?: string | number,
    note: string = ''
  ) {
    if (!payload) {
      return null;
    }
    return {
      id:
        id ||
        `local:${Date.now()}:${Math.random()
          .toString(36)
          .slice(2)}`,
      type: 'manual' as const,
      bookKey: payload.tab.bookKey as string,
      bookName:
        payload.tab.bookName || payload.tab.name || (this.readerBook && this.readerBook.name) || payload.book,
      language: payload.language,
      book: payload.book,
      link: payload.tab.link as string,
      location: payload.tab.location || payload.section,
      position: payload.position,
      anchor: payload.anchor,
      note,
      updatedAt: new Date().toISOString()
    };
  }

  async addBookmarkAtCurrentPlace(note: string = '') {
    const payload = this.currentBookmarkPayload();
    const local = this.localBookmark(payload, undefined, note);
    if (!(payload && local)) {
      return;
    }
    this.$store.commit('bookmarks/upsert', local);
    if (this.$store.state.auth.authorized) {
      try {
        const saved = await UserService.createBookmark({
          language: payload.language,
          book: payload.book,
          section: payload.section,
          position: payload.position,
          paragraph_anchor: payload.anchor,
          note
        });
        const bookmark = saved ? mapServerBookmark(saved) : null;
        if (bookmark) {
          this.$store.commit('bookmarks/remove', local.id);
          this.$store.commit('bookmarks/upsert', bookmark);
        }
      } catch (e) {
        // The local bookmark remains available until synchronization can be retried.
      }
    }
    this.mobileBookmarkSheetVisible = false;
  }

  async moveBookmarkToCurrentPlace(bookmark: Bookmark) {
    const payload = this.currentBookmarkPayload();
    if (!(payload && bookmark.bookKey === payload.tab.bookKey)) {
      return;
    }
    const moved = this.localBookmark(payload, bookmark.id, bookmark.note || '');
    if (!moved) {
      return;
    }
    this.$store.commit('bookmarks/upsert', moved);
    if (this.$store.state.auth.authorized && typeof bookmark.id === 'number') {
      try {
        const saved = await UserService.updateBookmark(bookmark.id, {
          language: payload.language,
          book: payload.book,
          section: payload.section,
          position: payload.position,
          paragraph_anchor: payload.anchor,
          note: bookmark.note || ''
        });
        const serverBookmark = mapServerBookmark(saved);
        if (serverBookmark) {
          this.$store.commit('bookmarks/upsert', serverBookmark);
        }
      } catch (e) {
        this.$store.commit('bookmarks/upsert', bookmark);
      }
    }
    this.mobileBookmarkSheetVisible = false;
  }

  async removeBookmark(bookmark: Bookmark) {
    this.$store.commit('bookmarks/remove', bookmark.id);
    if (this.$store.state.auth.authorized && typeof bookmark.id === 'number') {
      UserService.removeBookmark(bookmark.id).catch(() => {
        this.$store.commit('bookmarks/upsert', bookmark);
      });
    }
  }

  async updateBookmarkNote(payload: { bookmark: Bookmark; note: string }) {
    const updated = {
      ...payload.bookmark,
      note: payload.note,
      updatedAt: new Date().toISOString()
    };
    this.$store.commit('bookmarks/upsert', updated);
    if (
      !this.$store.state.auth.authorized ||
      typeof payload.bookmark.id !== 'number' ||
      !UserService.bookmarksApiEnabled
    ) {
      return;
    }
    const segments = payload.bookmark.link
      .split('?')[0]
      .split('/')
      .filter(Boolean);
    const section = segments[segments.length - 1] === payload.bookmark.book ? '' : segments.pop() || '';
    try {
      const saved = await UserService.updateBookmark(payload.bookmark.id, {
        language: payload.bookmark.language,
        book: payload.bookmark.book,
        section,
        position: payload.bookmark.position,
        paragraph_anchor: payload.bookmark.anchor || '',
        note: payload.note
      });
      const bookmark = saved ? mapServerBookmark(saved) : null;
      if (bookmark) {
        this.$store.commit('bookmarks/upsert', bookmark);
      }
    } catch (e) {
      this.$store.commit('bookmarks/upsert', payload.bookmark);
    }
  }

  async openMobileBookmark(bookmark: Bookmark) {
    const sectionSlug = bookmark.link
      .split('?')[0]
      .split('/')
      .filter(Boolean)
      .pop();
    const storedSection = sectionSlug && sectionSlug !== bookmark.book ? sectionSlug : '';
    await this.prepareMobileReaderNavigation(bookmark.language, bookmark.book, storedSection);
    const resolvedSection =
      typeof this.resolveBookmarkSection === 'function' ? this.resolveBookmarkSection(bookmark) : '';
    const bookmarkSection = resolvedSection || storedSection;
    if (bookmarkSection && bookmarkSection !== storedSection) {
      await this.prepareMobileReaderNavigation(bookmark.language, bookmark.book, bookmarkSection);
    }
    const bookmarkLink =
      bookmarkSection && bookmarkSection !== storedSection
        ? this.replaceBookmarkSectionInLink(bookmark.link, bookmark.book, bookmarkSection)
        : bookmark.link;
    this.$store.commit('tabs/activateBookTab', {
      bookKey: bookmark.bookKey,
      link: bookmarkLink,
      name: `${bookmark.bookName} — ${bookmark.location}`,
      bookName: bookmark.bookName,
      location: bookmark.location,
      position: bookmark.position,
      paragraphAnchor: bookmark.anchor || ''
    });
    this.$store.commit('tabs/keepOnlyActiveTab');
    const bookmarkRoute = {
      path: bookmarkLink,
      query: {
        bookmark: '1',
        ...(bookmark.anchor ? { anchor: bookmark.anchor } : {}),
        reading: '1'
      }
    };
    if (this.$route.path !== bookmarkLink || this.$route.query.anchor !== bookmark.anchor) {
      try {
        await this.$router.push(bookmarkRoute);
      } catch (error) {
        if (!(error && (error as { name?: string }).name === 'NavigationDuplicated')) {
          return;
        }
      }
    }
    this.mobileView = 'content';
  }

  onReaderLinkSelected(payload: { link: string; name: string }) {
    const bookKey = getBookKeyFromLink(payload.link);
    if (bookKey) {
      const sectionLink = isBookSectionLink(payload.link);
      this.$store.commit('tabs/activateBookTab', {
        bookKey,
        link: payload.link,
        name: payload.name,
        bookName: sectionLink ? undefined : payload.name,
        location: sectionLink ? payload.name : undefined,
        preserveLastLocation: !sectionLink
      });
    } else {
      this.$store.commit('tabs/updateActiveTabLink', payload.link);
      this.$store.commit('tabs/updateActiveTabName', payload.name);
    }
    if (!this.isCompactViewport) {
      return;
    }
    this.$store.commit('tabs/keepOnlyActiveTab');
    this.mobileCatalogVisible = false;
    this.mobileView = 'content';
    if (payload.link.split('?')[0] === this.$route.path) {
      this.syncMobileViewWithRoute();
    }
  }

  onMouseMove(e: MouseEvent) {
    let leftColumnWidth = this.leftColumnWidth;
    leftColumnWidth += e.pageX - this.prevPageX;
    leftColumnWidth = Reader.normalizeLeftColumnWidth(leftColumnWidth);
    this.leftColumnWidth = leftColumnWidth;
    this.prevPageX = e.pageX;
  }

  onMouseUp() {
    StorageService.save(LEFT_COLUMN_LOCAL_STORAGE_PARAM, this.leftColumnWidth);
    document.removeEventListener('mousemove', this.onMouseMove);
    document.removeEventListener('mouseup', this.onMouseUp);
    document.body.classList.remove('disable-text-select');
  }

  onMouseDown(e: MouseEvent) {
    document.addEventListener('mousemove', this.onMouseMove);
    document.addEventListener('mouseup', this.onMouseUp);
    document.body.classList.add('disable-text-select');
    this.prevPageX = e.pageX;
  }

  static normalizeLeftColumnWidth(leftColumnWidth: number) {
    let normalized = Math.min(leftColumnWidth, MAX_LEFT_COLUMN_WIDTH);
    normalized = Math.max(normalized, MIN_LEFT_COLUMN_WIDTH);
    return normalized;
  }
}
