





















































import Vue from 'vue';
import Component from 'vue-class-component';
import { Prop, Watch } from 'vue-property-decorator';
import { Mutation, State } from 'vuex-class';
import { getTranslation } from '@/services/Translation';

type ColorMode = 'light' | 'mixed' | 'dark';

@Component
export default class MobileReaderThemePicker extends Vue {
  @Prop({ required: true, default: false })
  visible!: boolean;

  @State('colorMode', { namespace: 'reader' })
  colorMode!: ColorMode;

  @Mutation('setColorMode', { namespace: 'reader' })
  setColorMode!: (colorMode: ColorMode) => void;

  dragStartY: number | null = null;

  dragOffset: number = 0;

  dragPointerId: number | null = null;

  dragging: boolean = false;

  previouslyFocused: HTMLElement | null = null;

  getTranslation = getTranslation;

  get themes() {
    return [
      { code: 'light' as ColorMode, name: getTranslation('colorThemeLight') },
      { code: 'mixed' as ColorMode, name: getTranslation('colorThemeMixed') },
      { code: 'dark' as ColorMode, name: getTranslation('colorThemeDark') }
    ];
  }

  mounted() {
    document.addEventListener('keydown', this.onDocumentKeydown);
    if (this.visible) {
      this.focusDialog();
    }
  }

  beforeDestroy() {
    document.removeEventListener('keydown', this.onDocumentKeydown);
    this.restoreFocus();
  }

  @Watch('visible')
  onVisibleChange(visible: boolean) {
    if (visible) {
      this.focusDialog();
    } else {
      this.restoreFocus();
    }
  }

  selectTheme(theme: ColorMode) {
    this.setColorMode(theme);
  }

  focusDialog() {
    const activeElement = document.activeElement;
    this.previouslyFocused =
      activeElement instanceof HTMLElement && activeElement !== document.body ? activeElement : null;
    this.$nextTick(() => {
      const dialog = this.$refs.dialog as HTMLElement;
      if (dialog) {
        dialog.focus();
      }
    });
  }

  restoreFocus() {
    if (this.previouslyFocused && document.contains(this.previouslyFocused)) {
      this.previouslyFocused.focus();
    }
    this.previouslyFocused = null;
  }

  onDocumentKeydown(event: KeyboardEvent) {
    if (!this.visible) {
      return;
    }
    if (event.key === 'Escape') {
      event.preventDefault();
      this.$emit('close');
      return;
    }
    if (event.key !== 'Tab') {
      return;
    }
    const dialog = this.$refs.dialog as HTMLElement;
    const options = dialog
      ? (Array.from(dialog.querySelectorAll('button:not([disabled])')) as HTMLElement[])
      : [];
    if (!options.length) {
      event.preventDefault();
      dialog.focus();
      return;
    }
    const first = options[0];
    const last = options[options.length - 1];
    if (event.shiftKey && (document.activeElement === first || document.activeElement === dialog)) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault();
      first.focus();
    }
  }

  startDrag(event: PointerEvent) {
    this.dragPointerId = event.pointerId;
    this.dragStartY = event.clientY;
    this.dragging = true;
    const target = event.currentTarget as HTMLElement;
    if (target.setPointerCapture) {
      target.setPointerCapture(event.pointerId);
    }
  }

  moveDrag(event: PointerEvent) {
    if (this.dragStartY === null || this.dragPointerId !== event.pointerId) {
      return;
    }
    this.dragOffset = Math.max(0, event.clientY - this.dragStartY);
    if (this.dragOffset && event.cancelable) {
      event.preventDefault();
    }
  }

  endDrag(event: PointerEvent) {
    if (this.dragPointerId !== event.pointerId) {
      return;
    }
    if (this.dragOffset >= 64) {
      this.resetDrag();
      this.$emit('close');
      return;
    }
    this.resetDrag();
  }

  cancelDrag() {
    this.resetDrag();
  }

  resetDrag() {
    this.dragStartY = null;
    this.dragOffset = 0;
    this.dragPointerId = null;
    this.dragging = false;
  }
}
