import Vue from 'vue';
import Component from 'vue-class-component';
import { Prop } from 'vue-property-decorator';
import ArrowLeftIcon from '@/assets/icons/nav-arrow-left.svg';
import ArrowRightIcon from '@/assets/icons/nav-arrow-right.svg';
import MinusIcon from '@/assets/icons/minus.svg';
import PlusIcon from '@/assets/icons/plus.svg';
import BottomBarControlValue from '@/components/bottom-bar/BottomBarControlValue.vue';
import { Mutation } from 'vuex-class';

@Component({
  components: {
    BottomBarControlValue,
    ArrowLeftIcon,
    ArrowRightIcon,
    MinusIcon,
    PlusIcon
  }
})
export default class BottomBarControl extends Vue {
  @Prop({ required: true })
  name!: string;

  @Prop({ required: false })
  number!: number;

  @Prop({ required: true })
  type!: string;

  @Prop({ required: false })
  list!: Array<number>;

  @Prop({ required: false })
  prevUrl!: string;

  @Prop({ required: false })
  nextUrl!: string;

  @Prop({ required: false })
  canIncreaseScale!: boolean;

  @Prop({ required: false })
  canDecreaseScale!: boolean;

  @Mutation('setColorMode', { namespace: 'reader' })
  setColorMode!: Function;
}
