import { Author, AuthorLetter, BookLetter, Books, Category } from '@/services/Navigation/types';

export default class ExpandService {
  /**
   * This method will DO the mutation of data in order to not re-render every DOM node
   */
  public static toggleCategoryExpand(categories: Array<Category>, categoryId: number) {
    const index = categories.findIndex(category => categoryId === category.id);
    if (index > -1) {
      categories[index].expanded = !categories[index].expanded;
    }
  }

  /**
   * This method will DO the mutation of data in order to not re-render every DOM node
   */
  public static toggleAuthorExpand(authors: Array<Author>, authorId: number) {
    const index = authors.findIndex(author => authorId === author.id);
    if (index > -1) {
      authors[index].expanded = !authors[index].expanded;
    }
  }

  /**
   * This method will DO the mutation of data in order to not re-render every DOM node
   */
  public static toggleLetterExpand(letters: Array<BookLetter | AuthorLetter>, letterId: number) {
    const index = letters.findIndex(letter => letterId === letter.id);
    if (index > -1) {
      letters[index].expanded = !letters[index].expanded;
    }
  }

  /**
   * This method will DO the mutation of data in order to not re-render every DOM node
   */
  public static toggleBookExpand(books: Books, bookSlug: string) {
    books[bookSlug].expanded = !books[bookSlug].expanded;
  }

  /**
   * This method will DO the mutation of data in order to not re-render every DOM node
   */
  public static toggleBookSectionExpand(books: Books, bookSectionId: string, bookSlug: string) {
    const index = books[bookSlug].children.findIndex(bookSection => bookSectionId === bookSection.id);
    if (index > -1) {
      books[bookSlug].children[index].expanded = !books[bookSlug].children[index].expanded;
    }
  }

  /**
   * This method will DO the mutation of data in order to not re-render every DOM node
   */
  public static toggleFoundBookSectionExpand(books: Books, bookSectionId: string, bookSlug: string) {
    if (!books[bookSlug]) {
      return;
    }
    const index = books[bookSlug].children.findIndex(bookSection => bookSectionId === bookSection.id);
    if (index > -1) {
      books[bookSlug].children[index].expanded = !books[bookSlug].children[index].expanded;
    }
  }
}
