import { Book, Category } from '@/services/Navigation/types';

export interface SearchScopeOptions {
  book_slug?: string;
  books?: Array<number>;
  categories?: Array<number>;
  book_sections?: Array<string>;
}

export interface CategoryBookMapping {
  id: number | string;
  books: Array<number>;
}

export default class SearchScopeService {
  static hasActiveScope(options: SearchScopeOptions = {}) {
    return (
      !!options.book_slug ||
      !!(options.books && options.books.length) ||
      !!(options.categories && options.categories.length) ||
      !!(options.book_sections && options.book_sections.length)
    );
  }

  static getBranchCategoryIds(categories: Array<Category>, categoryId: number) {
    const branchIds = new Set<number>([Number(categoryId)]);
    let previousSize = 0;
    while (branchIds.size !== previousSize) {
      previousSize = branchIds.size;
      categories.forEach(category => {
        if (branchIds.has(Number(category.parent_id))) {
          branchIds.add(Number(category.id));
        }
      });
    }
    return branchIds;
  }

  static getUnloadedBookCategoryIds(categories: Array<Category>, categoryId: number) {
    const branchIds = SearchScopeService.getBranchCategoryIds(categories, categoryId);
    return categories
      .filter(category => {
        return branchIds.has(Number(category.id)) && category.is_books_exist && !category.bookIds.length;
      })
      .map(category => Number(category.id));
  }

  static applyCategoryBookMappings(
    categories: Array<Category>,
    requestedCategoryIds: Array<number>,
    mappings: Array<CategoryBookMapping>
  ) {
    const requestedIds = new Set(requestedCategoryIds.map(Number));
    const mappingById = new Map(mappings.map(mapping => [Number(mapping.id), mapping.books.map(Number)]));
    return categories.map(category =>
      requestedIds.has(Number(category.id))
        ? {
            ...category,
            bookIds: mappingById.get(Number(category.id)) || []
          }
        : category
    );
  }

  static getSelectedBookIds(books: Array<Book>, categories: Array<Category>) {
    const selectedBookIds = new Set<number>();
    books.forEach(book => selectedBookIds.add(Number(book.id)));
    categories.forEach(category => {
      category.bookIds.forEach(bookId => selectedBookIds.add(Number(bookId)));
    });
    return selectedBookIds;
  }
}
